class Solution {
public:
    long long maximumSumScore(vector<int>& nums) {
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        long long prefix = 0, answer = LLONG_MIN;
        for (int x : nums) {
            prefix += x;
            answer = max(answer, max(prefix, total - prefix + x));
        }
        return answer;
    }
};
